#!/usr/bin/env python3
# LinBASIC Studio - tests of the run-time checks: Checks.bas (generated by gen6.py) measures what VB6 does on
# integer overflow, out-of-range array indices, floating-point errors and precision, and what the advanced
# optimizations of the Compile tab change (Remove Integer Overflow / Array Bounds / Floating Point Error Checks,
# Allow Unrounded Floating Point Operations). It is compiled with lbvc as each VB6 build was made, and its output
# is compared line by line with what the VB6 SP6 build printed (expected/BUILD.txt, Greek regional settings).
# Copyright (C) 2026 Demosthenes Koptsis. GPL-3.0-or-later.
#   python3 tests/checks/run_tests.py [ChkFast ...]
import glob, os, re, shutil, subprocess, sys
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, '..', '..', 'compiler'))
from lbvc.driver import compile_project, build_exe, find_runtime, parse_order   # noqa: E402

ALL = 'overflow,bounds,flpoint,unrounded'
BUILDS = {'ChkPcodeAll': 'pcode', 'ChkFast': 'fast', 'ChkOverflow': 'fast,overflow', 'ChkBounds': 'fast,bounds',
          'ChkFlPoint': 'fast,flpoint', 'ChkUnrounded': 'fast,unrounded', 'ChkFastAll': 'fast,' + ALL,
          'ChkNoOptAll': 'noopt,' + ALL}


def lines(data):
    return data.decode('cp1252').replace('\r', '').rstrip('\n').split('\n')


def run(build, rt, work):
    d = os.path.join(work, build)
    shutil.rmtree(d, ignore_errors=True)
    os.makedirs(d)
    src = open(os.path.join(HERE, 'Checks.bas'), 'rb').read()
    src = re.sub(rb'(?m)^\s*MsgBox "Done.*$', b'', src)
    f = os.path.join(d, 'Checks.bas')
    open(f, 'wb').write(src)
    csrc, _ = compile_project([f], order=parse_order(BUILDS[build]))
    exe = build_exe(csrc, os.path.join(d, build), rt) or os.path.join(d, build)
    env = dict(os.environ, VBRT_NO_ERRBOX='1', VBRT_LCID='1032', VBRT_CODEPAGE='1253')
    subprocess.run([exe], cwd=d, capture_output=True, timeout=120, env=env)
    out = os.path.join(d, build + '.txt')
    return lines(open(out, 'rb').read()) if os.path.exists(out) else []


def main():
    names = [n for n in BUILDS if not sys.argv[1:] or n in sys.argv[1:]]
    rt = find_runtime()
    work = os.path.join(HERE, 'work')
    failed = 0
    for n in names:
        want = lines(open(os.path.join(HERE, 'expected', n + '.txt'), 'rb').read())
        try:
            got = run(n, rt, work)
        except Exception as e:
            print(f"FAIL {n} (compile): {e}")
            failed += 1
            continue
        bad = [(w, g) for w, g in zip(want, got) if w != g]
        if len(got) != len(want):
            bad.append((f"{len(want)} lines", f"{len(got)} lines"))
        if bad:
            failed += 1
            print(f"FAIL {n}: {len(bad)} of {len(want)} lines differ")
            for w, g in bad[:int(os.environ.get('SHOW', '6'))]:
                print(f"    VB6:      {w}\n    LinBASIC: {g}")
        else:
            print(f"ok   {n} ({len(want)} lines)")
    print(f"{len(names) - failed} passed, {failed} failed")
    return 1 if failed else 0


if __name__ == '__main__':
    sys.exit(main())
